def solve(line, width):
    out = []
    current_indent = 0
    for c in line:
        if c == '\t':
            # Calculate how many spaces to add for this tab
            spaces = (current_indent // width) * width
            out.append(' ' * spaces)
            current_indent += width
        else:
            out.append(c)
    # Add the remaining spaces to reach the next tab stop
    if current_indent % width != 0:
        out.append(' ' * (width - current_indent % width))
    return ''.join(out)
```

